import os
from pathlib import Path

www = Path(os.environ['ANDROID_DIR']) / 'app/src/main/assets/www'
index = www / 'index.html'
if not index.exists():
    raise SystemExit('index.html nao encontrado')

# V28: camada visual nova, sem reutilizar screenshots como fundo.
css = r'''
:root{--v28-bg:#07111d;--v28-card:#0d1b2a;--v28-card2:#122338;--v28-line:#213a55;--v28-txt:#f4f8fb;--v28-mut:#8ea3b7;--v28-green:#27e2ad;--v28-blue:#35a9ff;--v28-gold:#f4c85e;--safe-b:env(safe-area-inset-bottom,0px)}
#msV28{position:fixed;inset:0;z-index:2147483640;background:radial-gradient(circle at 80% 0,#183c6455,transparent 38%),linear-gradient(#07111d,#050c14);color:var(--v28-txt);font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,sans-serif;overflow:hidden}
#msV28 *{box-sizing:border-box}.v28-shell{height:100dvh;max-width:760px;margin:auto;display:grid;grid-template-rows:auto 1fr auto}.v28-top{padding:max(14px,env(safe-area-inset-top)) 16px 12px;display:flex;align-items:center;gap:10px;border-bottom:1px solid #14283b;background:#07111dec;backdrop-filter:blur(14px)}.v28-logo{width:42px;height:42px;border-radius:13px;display:grid;place-items:center;background:linear-gradient(145deg,var(--v28-green),var(--v28-blue));color:#031b18;font-weight:1000}.v28-title{font-weight:950;font-size:19px}.v28-sub{font-size:11px;color:var(--v28-mut)}.v28-status{margin-left:auto;font-size:11px;padding:7px 9px;border:1px solid #294761;border-radius:999px;color:#a8bdcf}.v28-status.ok{border-color:#178667;color:#7ce8cb}.v28-main{overflow:auto;padding:14px 14px calc(16px + var(--safe-b));overscroll-behavior:contain}.v28-view{display:none}.v28-view.on{display:block}.v28-card{border:1px solid var(--v28-line);border-radius:22px;background:linear-gradient(180deg,#0f2033,#0a1725);box-shadow:0 16px 42px #0007,inset 0 1px #ffffff0a}.v28-hero{padding:18px;min-height:440px;position:relative;overflow:hidden}.v28-stadium{position:absolute;inset:0;background:radial-gradient(ellipse at 50% 12%,#55bfff44,transparent 18%),linear-gradient(180deg,#0d2a46 0 40%,#0b362d 40% 100%)}.v28-stadium:before{content:'';position:absolute;left:5%;right:5%;top:42%;height:38%;border:2px solid #d7fff744;border-radius:50% 50% 10% 10%;box-shadow:0 0 40px #30cfff18}.v28-stadium:after{content:'';position:absolute;left:12%;right:12%;bottom:7%;height:27%;border-top:2px solid #d8fff74a;border-radius:50%;background:repeating-linear-gradient(90deg,#1b7e5515 0 36px,#0d5f4115 36px 72px)}.v28-character{position:absolute;left:50%;bottom:68px;transform:translateX(-50%);width:210px;height:285px;filter:drop-shadow(0 22px 28px #0009)}.v28-character img{width:100%;height:100%;object-fit:contain}.v28-level{position:absolute;left:14px;top:14px;background:#07131fcc;border:1px solid #32516c;border-radius:16px;padding:10px 12px;backdrop-filter:blur(8px)}.v28-level b{display:block;font-size:30px}.v28-power{position:absolute;right:14px;top:14px;text-align:right;background:#07131fcc;border:1px solid #6d5828;border-radius:16px;padding:10px 12px}.v28-power b{display:block;color:var(--v28-gold);font-size:20px}.v28-xp{position:absolute;left:14px;right:14px;bottom:14px;padding:10px 12px;background:#07131fe8;border:1px solid #31506a;border-radius:15px}.v28-bar{height:9px;border-radius:99px;background:#172a3e;overflow:hidden;margin-top:7px}.v28-bar i{display:block;width:62%;height:100%;background:linear-gradient(90deg,var(--v28-green),var(--v28-blue))}.v28-grid{display:grid;gap:10px}.v28-match{padding:14px;display:grid;grid-template-columns:1fr auto 1fr;gap:10px;align-items:center}.v28-team{text-align:center}.v28-team img{width:42px;height:42px;object-fit:contain;display:block;margin:0 auto 6px}.v28-team b{font-size:12px}.v28-score{font-size:20px;font-weight:950}.v28-meta{text-align:center;color:var(--v28-mut);font-size:10px;margin-top:4px}.v28-empty{padding:22px;text-align:center;color:var(--v28-mut)}.v28-section-title{font-size:22px;font-weight:950;margin:3px 2px 12px}.v28-items{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.v28-item{padding:13px;min-height:130px}.v28-item .ico{width:50px;height:50px;border-radius:15px;background:linear-gradient(145deg,#173857,#0d2034);display:grid;place-items:center;font-size:26px;border:1px solid #33516c}.v28-item h3{font-size:13px;margin:9px 0 4px}.v28-item small{color:var(--v28-mut)}.v28-equip{margin-top:9px;width:100%;padding:9px;border-radius:11px;border:1px solid #34526c;background:#10243a;color:white;font-weight:850}.v28-equip.on{border-color:#21c895;background:#0d715c}.v28-nav{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;padding:10px 12px calc(10px + var(--safe-b));border-top:1px solid #172a3c;background:#07111df2;backdrop-filter:blur(14px)}.v28-nav button{border:0;background:transparent;color:#8095a9;padding:8px 4px;border-radius:12px;font:inherit;font-size:11px;font-weight:800}.v28-nav button span{display:block;font-size:20px;margin-bottom:2px}.v28-nav button.on{background:#10263a;color:white}.v28-toast{position:fixed;left:50%;bottom:calc(86px + var(--safe-b));transform:translateX(-50%);padding:10px 14px;border-radius:12px;background:#0b1b2af2;border:1px solid #294963;color:white;display:none;z-index:2147483646}.v28-toast.on{display:block}
@media(min-width:600px){.v28-items{grid-template-columns:repeat(3,1fr)}.v28-hero{min-height:500px}.v28-character{width:250px;height:340px}}
'''
(www/'v28.css').write_text(css,encoding='utf-8')

# Quatro quadros SVG distintos para animacao real do personagem (idle).
frames = [
('0','0','0'),('2','-2','1'),('0','0','0'),('-2','2','-1')
]
for n,(dx,dy,rot) in enumerate(frames):
    svg=f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 220 300"><defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#27e2ad"/><stop offset="1" stop-color="#2578ff"/></linearGradient></defs><g transform="translate({dx} {dy}) rotate({rot} 110 160)"><circle cx="110" cy="52" r="34" fill="#d7a47e"/><path d="M78 49q32-42 66 0v-17q-35-28-66 0z" fill="#162235"/><path d="M75 92q35-18 70 0l18 95-27 8-10-67-8 78h-16l-8-78-10 67-27-8z" fill="url(#g)"/><path d="M91 93h38l-4 28H95z" fill="#f6f8fb" opacity=".95"/><text x="110" y="114" text-anchor="middle" font-family="Arial" font-size="16" font-weight="900" fill="#0a2030">28</text><path d="M91 206l-8 67h20l13-67zM118 206l0 67h20l-4-67z" fill="#101c2b"/><path d="M79 272h28v12H73q0-8 6-12zM116 272h25l8 12h-34z" fill="#25d6a8"/><circle cx="98" cy="52" r="3" fill="#15202d"/><circle cx="121" cy="52" r="3" fill="#15202d"/><path d="M100 68q10 7 20 0" stroke="#733f33" stroke-width="3" fill="none" stroke-linecap="round"/></g></svg>'''
    (www/f'v28-player-{n}.svg').write_text(svg,encoding='utf-8')

js = r'''(()=>{'use strict';
const API='https://matchscope-kjf9.onrender.com';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const state={tab:'home',frame:0,equipped:'armor'};
const items=[['armor','🛡️','Armadura do Campeão','Lendário · +20% XP'],['boots','👟','Chuteiras do Vento','Épico · +10% XP'],['staff','✨','Cajado Arcano','Lendário · +20% XP'],['cape','🧥','Manto das Estrelas','Épico · +10% XP'],['crown','👑','Coroa Celestial','Lendário · +20% XP'],['book','📘','Grimório','Raro · +5% XP']];
function shell(){if($('#msV28'))return;document.body.insertAdjacentHTML('beforeend',`<div id="msV28"><div class="v28-shell"><header class="v28-top"><div class="v28-logo">MS</div><div><div class="v28-title">MatchScore</div><div class="v28-sub">Futebol + RPG</div></div><div id="v28Api" class="v28-status">API...</div></header><main class="v28-main"><section class="v28-view on" data-view="home"><div class="v28-section-title">Hoje</div><div id="v28Matches" class="v28-grid"><div class="v28-card v28-empty">Carregando partidas reais...</div></div></section><section class="v28-view" data-view="player"><div class="v28-card v28-hero"><div class="v28-stadium"></div><div class="v28-level"><small>NÍVEL</small><b>28</b></div><div class="v28-power"><small>FORÇA</small><b>1.842</b></div><div class="v28-character"><img id="v28Player" src="v28-player-0.svg" alt="Jogador animado"></div><div class="v28-xp"><small>XP 6.200 / 10.000</small><div class="v28-bar"><i></i></div></div></div></section><section class="v28-view" data-view="items"><div class="v28-section-title">Equipamentos</div><div id="v28Items" class="v28-items"></div></section><section class="v28-view" data-view="rank"><div class="v28-section-title">Ranking</div><div class="v28-card v28-empty">Ranking da temporada · níveis 1–200<br><small>Atualização online será integrada ao backend.</small></div></section></main><nav class="v28-nav"><button class="on" data-tab="home"><span>⚽</span>Jogos</button><button data-tab="player"><span>🧍</span>Jogador</button><button data-tab="items"><span>🎒</span>Itens</button><button data-tab="rank"><span>🏆</span>Ranking</button></nav></div><div id="v28Toast" class="v28-toast"></div></div>`); bind(); renderItems(); loadMatches(); animate(); history.replaceState({v28:'home'},'');}
function bind(){$$('.v28-nav button').forEach(b=>b.onclick=()=>go(b.dataset.tab,true)); window.addEventListener('popstate',e=>{const t=e.state?.v28||'home';go(t,false)});}
function go(tab,push){state.tab=tab;$$('.v28-view').forEach(v=>v.classList.toggle('on',v.dataset.view===tab));$$('.v28-nav button').forEach(b=>b.classList.toggle('on',b.dataset.tab===tab));if(push)history.pushState({v28:tab},'');}
function animate(){setInterval(()=>{state.frame=(state.frame+1)%4;const p=$('#v28Player');if(p)p.src=`v28-player-${state.frame}.svg`;},180);}
function renderItems(){const root=$('#v28Items');root.innerHTML=items.map(([id,ico,name,meta])=>`<div class="v28-card v28-item"><div class="ico">${ico}</div><h3>${name}</h3><small>${meta}</small><button class="v28-equip ${state.equipped===id?'on':''}" data-e="${id}">${state.equipped===id?'Equipado':'Equipar'}</button></div>`).join('');$$('[data-e]',root).forEach(b=>b.onclick=()=>{state.equipped=b.dataset.e;renderItems();toast('Item equipado');});}
function toast(t){const el=$('#v28Toast');el.textContent=t;el.classList.add('on');setTimeout(()=>el.classList.remove('on'),1400)}
function dateLocal(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function esc(s){return String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
async function loadMatches(){const stat=$('#v28Api'),root=$('#v28Matches');try{const r=await fetch(`${API}/fixtures?date=${dateLocal()}`,{headers:{Accept:'application/json'}});if(!r.ok)throw new Error(`HTTP ${r.status}`);const j=await r.json();if(!Array.isArray(j.response))throw new Error('Resposta invalida');stat.textContent=`API OK · ${j.response.length}`;stat.classList.add('ok');if(!j.response.length){root.innerHTML='<div class="v28-card v28-empty">Nenhuma partida encontrada para hoje.</div>';return;}root.innerHTML=j.response.slice(0,30).map(m=>{const h=m.teams?.home||{},a=m.teams?.away||{},gh=m.goals?.home,ga=m.goals?.away,when=m.fixture?.date?new Date(m.fixture.date).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'}):'';return `<div class="v28-card v28-match"><div class="v28-team">${h.logo?`<img src="${esc(h.logo)}">`:''}<b>${esc(h.name||'Casa')}</b></div><div><div class="v28-score">${gh??'-'} × ${ga??'-'}</div><div class="v28-meta">${esc(when)} · ${esc(m.league?.name||'')}</div></div><div class="v28-team">${a.logo?`<img src="${esc(a.logo)}">`:''}<b>${esc(a.name||'Fora')}</b></div></div>`}).join('');}catch(e){stat.textContent='API indisponível';stat.classList.remove('ok');root.innerHTML=`<div class="v28-card v28-empty">Não foi possível carregar os jogos.<br><small>${esc(e.message)}</small></div>`;}}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',shell);else shell();
})();'''
(www/'v28.js').write_text(js,encoding='utf-8')

html=index.read_text(encoding='utf-8')
# Remove apenas inclusoes V27 para impedir que a tela antiga reapareca por cima.
html=html.replace('<link rel="stylesheet" href="beta-v27.css?v=27">','').replace('<link rel="stylesheet" href="beta-v27.css">','')
html=html.replace('<script src="beta-v27.js?v=27"></script>','').replace('<script src="beta-v27.js"></script>','')
if 'v28.css' not in html: html=html.replace('</head>','<link rel="stylesheet" href="v28.css?v=28">\n</head>')
if 'v28.js' not in html: html=html.replace('</body>','<script src="v28.js?v=28"></script>\n</body>')
index.write_text(html,encoding='utf-8')
print('V28 aplicada: UI nova, Sportmonks via backend e personagem com 4 quadros SVG.')
